CREATE OR REPLACE FUNCTION public.complete_learning_lesson(p_lesson text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; n integer; sections integer; BEGIN SELECT parcours INTO p FROM public.profiles WHERE id=auth.uid(); IF p IS NULL THEN RAISE EXCEPTION 'Connectez-vous pour terminer cette leçon.'; END IF; IF EXISTS(SELECT 1 FROM public.learning_completions WHERE user_id=auth.uid() AND parcours=p AND lesson_id=p_lesson) THEN RETURN; END IF; SELECT position,cardinality(body) INTO n,sections FROM public.learning_lessons WHERE id=p_lesson AND published; IF n IS NULL OR sections=0 THEN RAISE EXCEPTION 'Le contenu de cette leçon est en cours de préparation.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.learning_reading_positions WHERE user_id=auth.uid() AND parcours=p AND lesson_id=p_lesson AND section_index=sections-1) THEN RAISE EXCEPTION 'Lisez toutes les sections avant de terminer la leçon.'; END IF; IF EXISTS(SELECT 1 FROM public.learning_lessons l WHERE l.published AND l.position<n AND NOT EXISTS(SELECT 1 FROM public.learning_completions c WHERE c.user_id=auth.uid() AND c.parcours=p AND c.lesson_id=l.id)) THEN RAISE EXCEPTION 'Terminez d’abord la leçon précédente.'; END IF; INSERT INTO public.learning_completions(user_id,parcours,lesson_id) VALUES(auth.uid(),p,p_lesson) ON CONFLICT DO NOTHING; END $$;